const eventName=window.PointerEvent?'pointerdown':'touchstart';canvas.addEventListener(eventName,tap,{passive:false});document.querySelector('[data-restart]').addEventListener('click',restart);document.addEventListener('visibilitychange',()=>{last=0;});raf=requestAnimationFrame(frame);
